  "implementation": "def solve(case):
    # validate
    if 'edges' not in case or 'communities' not in case or 'resolution' not in case:
        raise ValueError('Missing required fields')
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']
    if not isinstance(edges, list) or not isinstance(communities, dict) or not isinstance(resolution, (int, float)):
        raise ValueError('Invalid types')

    # build adjacency and degrees
    adj = {}
    deg = {}
    total_weight = 0.0
    nodes = set()
    for u, v, w in edges:
        if not isinstance(w, (int, float)) or w <= 0:
            raise ValueError('Edge weight must be positive')
        nodes.add(u)
        nodes.add(v)
        total_weight += w
        adj.setdefault(u, {})[v] = adj[u].get(v, 0.0) + w
        adj.setdefault(v, {})[u] = adj[v].get(u, 0.0) + w
        deg[u] = deg.get(u, 0.0) + w
        deg[v] = deg.get(v, 0.0) + w
    # add nodes from communities that might not be in edges
    for n in communities:
        nodes.add(n)
        deg.setdefault(n, 0.0)
    # ensure all nodes have community assignment
    for n in nodes:
        if n not in communities:
            raise ValueError(f'Node {n} missing from communities')

    # initial partition and community degrees
    partition = dict(communities)
    community_degree = {}
    for node, comm in partition.items():
        d = deg[node]
        community_degree[comm] = community_degree.get(comm, 0.0) + d

    W = total_weight
    if W == 0:
        raise ValueError('Graph has no edges')

    moves = []
    node_order = sorted(nodes, key=str)

    # local moving: repeat until no move
    while True:
        moved = False
        for node in node_order:
            cur_comm = partition[node]
            d_i = deg[node]
            # weight to current community
            w_iA = 0.0
            for nb, w in adj.get(node, {}).items():
                if partition[nb] == cur_comm:
                    w_iA += w
            # candidate communities (neighbors not in current)
            cand_comms = set()
            for nb in adj.get(node, {}):
                nb_comm = partition[nb]
                if nb_comm != cur_comm:
                    cand_comms.add(nb_comm)
            best_gain = 0.0
            best_comm = None
            for cand_comm in cand_comms:
                # weight to candidate community
                w_iB = 0.0
                for nb, w in adj.get(node, {}).items():
                    if partition[nb] == cand_comm:
                        w_iB += w
                d_A = community_degree.get(cur_comm, 0.0)
                d_B = community_degree.get(cand_comm, 0.0)
                gain = (w_iB - w_iA) / W - (resolution * d_i * (d_i + d_B - d_A)) / (2.0 * W * W)
                if gain > best_gain or (gain == best_gain and cand_comm < best_comm):
                    best_gain = gain
                    best_comm = cand_comm
            if best_gain > 0:
                old_comm = cur_comm
                new_comm = best_comm
                partition[node] = new_comm
                community_degree[old_comm] -= d_i
                community_degree[new_comm] += d_i
                moves.append({'from': old_comm, 'node': node, 'to': new_comm})
                moved = True
        if not moved:
            break

    return {
        'communities': partition,
        'moves': moves
    }"
}
